export function territoireDemande(id: string) {
  return Object.hasOwn(TERRITOIRES_DEMANDE, id) ? TERRITOIRES_DEMANDE[id] : undefined;
}

export function regionDemande(id: string) {
  return Object.hasOwn(REGIONS_DEMANDE, id) ? REGIONS_DEMANDE[id] : undefined;
}

